import requests
from requests.models import Request

class FileWrapper:
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=None: b"test data"
        raise AttributeError(name)

def test_encode_files():
    print("Testing _encode_files with FileWrapper...")
    # We can test this by creating a Request and calling prepare()
    # or by calling the internal _encode_files if we can.
    # But the easiest is to use requests.post with files.

    files = {'file': FileWrapper()}
    # We use a mock URL
    try:
        # We don't actually want to send the request, just prepare it.
        req = requests.Request('POST', 'http://http://bin.org', files=files)
        prepared = req.prepare()
        print("Successfully prepared request")
        print(f"Body: {prepared.body}")
    except Exception as e:
        print(f"Failed: {e}")
        raise e

def test_encode_params():
    print("Testing _encode_params with FileWrapper...")
    # _encode_params is called when data is passed.
    # If data contains a FileWrapper, it should be handled.

    data = {'file': FileWrapper()}
    try:
        req = requests.Request('POST', 'http://http://bin.org', data=data)
        prepared = req.prepare()
        print("Successfully prepared request")
        print(f"Body: {prepared.body}")
    except Exception as e:
        print(f"Failed: {e}")
        raise e

if __name__ == "__main__":
    test_encode_files()
    test_encode_params()
    print("All tests passed!")
